## Plain JavaScript

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.querySelector('#search');
let controller;

async function search(query) {
  controller?.abort();                 // cancel the in-flight request
  if (!query.trim()) return renderResults([]);

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    renderResults(await res.json());
  } catch (err) {
    if (err.name !== 'AbortError') throw err;
  }
}

// Before: input.addEventListener('input', (e) => search(e.target.value));
input.addEventListener('input', debounce((e) => search(e.target.value), 300));
```

## React

```jsx
import { useEffect, useState } from 'react';

function useDebouncedValue(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

export function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }
    const controller = new AbortController();
    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => res.json())
      .then(setResults)
      .catch((err) => {
        if (err.name !== 'AbortError') throw err;
      });
    return () => controller.abort();   // cancel the stale request
  }, [debouncedQuery]);

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search…" />
      <ul>{results.map((r) => <li key={r.id}>{r.name}</li>)}</ul>
    </>
  );
}
```

`/api/search`, `renderResults`, and the `id`/`name` result fields are placeholders for your own.

- **Input stays responsive:** in the React version the input is bound to `query`, so typing updates instantly; only the API call waits on `debouncedQuery`.
- **Stale responses are cancelled:** debounce alone doesn't stop a slow earlier response from overwriting a newer one, which is why both versions abort the previous request.
- **Delay:** 300 ms is a common default; 150–250 ms feels snappier if your API is cheap.

